PART b: File Handling — Separate Even and Odd Numbers (7 marks)

#include <stdio.h>

int main() {
    FILE *fpNum, *fpEven, *fpOdd;
    int n, i, num;

    // Open NUMBER file for writing
    fpNum = fopen("NUMBER.txt", "w");
    if (fpNum == NULL) {
        printf("Error opening NUMBER file!\n");
        return 1;
    }

    printf("How many numbers to store? ");
    scanf("%d", &n);

    printf("Enter %d integers:\n", n);
    for (i = 0; i < n; i++) {
        scanf("%d", &num);
        fprintf(fpNum, "%d\n", num);  // Write to NUMBER file
    }
    fclose(fpNum);

    // Open NUMBER for reading, EVEN and ODD for writing
    fpNum = fopen("NUMBER.txt", "r");
    fpEven = fopen("EVEN.txt", "w");
    fpOdd = fopen("ODD.txt", "w");

    if (fpNum == NULL || fpEven == NULL || fpOdd == NULL) {
        printf("Error opening files!\n");
        return 1;
    }

    // Read from NUMBER and separate into EVEN and ODD
    while (fscanf(fpNum, "%d", &num) != EOF) {
        if (num % 2 == 0)
            fprintf(fpEven, "%d\n", num);  // Write to EVEN
        else
            fprintf(fpOdd, "%d\n", num);   // Write to ODD
    }

    fclose(fpNum);
    fclose(fpEven);
    fclose(fpOdd);

    // Display contents of all files
    printf("\n--- NUMBER file ---\n");
    fpNum = fopen("NUMBER.txt", "r");
    while (fscanf(fpNum, "%d", &num) != EOF)
        printf("%d ", num);
    fclose(fpNum);

    printf("\n--- EVEN file ---\n");
    fpEven = fopen("EVEN.txt", "r");
    while (fscanf(fpEven, "%d", &num) != EOF)
        printf("%d ", num);
    fclose(fpEven);

    printf("\n--- ODD file ---\n");
    fpOdd = fopen("ODD.txt", "r");
    while (fscanf(fpOdd, "%d", &num) != EOF)
        printf("%d ", num);
    fclose(fpOdd);

    printf("\n");
    return 0;
}

