PART a: Sum of Series using Recursion (6 marks)

Series: 1 + (1+2) + (1+2+3) + ... + (1+2+...+n)
Each term i = sum of first i natural numbers = i*(i+1)/2
Total = Σ i*(i+1)/2 for i=1 to n

Using Recursion:

#include <stdio.h>

// Calculate sum of 1 to k
int termSum(int k) {
    if (k == 1)
        return 1;
    return k + termSum(k - 1);
}

// Calculate series sum: term(1) + term(2) + ... + term(n)
int seriesSum(int n) {
    if (n == 1)
        return termSum(1);
    return termSum(n) + seriesSum(n - 1);
}

int main() {
    int n;
    printf("Enter n: ");
    scanf("%d", &n);

    printf("Sum of series = %d\n", seriesSum(n));
    return 0;
}

Sample Output:
Enter n: 4
Sum of series = 20

Trace for n=4:
seriesSum(4) = termSum(4) + seriesSum(3)
= 10 + (termSum(3) + seriesSum(2))
= 10 + (6 + (termSum(2) + seriesSum(1)))
= 10 + (6 + (3 + termSum(1)))
= 10 + 6 + 3 + 1 = 20

Alternative using Formula (without recursion):
#include <stdio.h>
int main() {
    int n, i, totalSum = 0;
    printf("Enter n: ");
    scanf("%d", &n);
    for (i = 1; i <= n; i++)
        totalSum += i * (i + 1) / 2;
    printf("Sum = %d\n", totalSum);
    return 0;
}

